/* Health Auto Export daily totals are server-owned and never merged into manual logs. */
let healthSnapshot=null,healthLoading=false,healthError='',healthKey='',healthKeyProfile='';
function healthForDate(date){if((healthSnapshot?.profile!==activeProfile||healthSnapshot?.account!==accountScope))return null;const out={};for(const r of healthSnapshot.readings||[])if(r.day===date)out[r.metric]=r.value;return Object.keys(out).length?out:null}
async function healthRequest(method='GET'){const r=await fetch('/api/health-link?profile='+encodeURIComponent(activeProfile)+'&day='+encodeURIComponent(selected),{method,credentials:'same-origin',headers:{'x-fitness-account':accountScope}});let b;try{b=await r.json()}catch{throw Error('تعذر الاتصال بخدمة الربط.')}if(!r.ok)throw Error(r.status===401?'جدّد تسجيل الدخول ثم أعد المحاولة.':'تعذر تحديث الربط؛ حاول مجددًا.');return b}
async function refreshHealth(){if(healthLoading||document.hidden)return;healthLoading=true;const profile=activeProfile,account=accountScope;try{const b=await healthRequest();if(profile!==activeProfile||account!==accountScope)return;const next={...b,profile,account},changed=JSON.stringify(next)!==JSON.stringify(healthSnapshot)||healthError;healthSnapshot=next;healthError='';if(changed)render()}catch(e){healthError=e.message;if(['settings','activity'].includes(view)){const status=document.querySelector('[data-health-status]');if(status)status.textContent=healthError}}finally{healthLoading=false}}
function healthAutomationURL(token){const p=new URLSearchParams({url:location.origin+'/api/health-import',name:'Fitness Tracker '+profileName(),format:'json',datatype:'healthMetrics',metrics:'Step Count,Walking + Running Distance,Active Energy,Apple Exercise Time,Weight & Body Mass,Body Fat Percentage,Lean Body Mass,Body Mass Index',period:'previous7days',aggregatedata:'true',interval:'days',batchrequests:'false',syncinterval:'hours',syncquantity:'1',headers:'X-Health-Key,'+token,enabled:'true',notifywhenrun:'false'});return 'com.HealthExport://automation?'+p.toString().replace(/\+/g,'%20')}
function healthStatus(){const h=healthSnapshot?.profile===activeProfile&&healthSnapshot?.account===accountScope?healthSnapshot:null;return healthError||(!h?'جارٍ التحقق من الربط…':!h.linked?'الربط غير مفعّل':h.lastReceived?'آخر استقبال: '+new Date(h.lastReceived).toLocaleString('ar-SA'):'تم إنشاء المفتاح؛ بانتظار أول بيانات من هاتفك.')}
function renderHealthSettings(){const h=healthSnapshot?.profile===activeProfile&&healthSnapshot?.account===accountScope?healthSnapshot:null,token=healthKeyProfile===activeProfile?healthKey:'';return `<section class="card" id="healthConnection"><div class="card-head"><div><h2>ربط الساعة وقياسات الجسم</h2><p class="sub">ملف الاستقبال: ${esc(profileName())}</p></div><button class="button secondary" data-health-refresh>تحديث الحالة</button></div><p class="notice" data-health-status>${esc(healthStatus())}</p><p>تنقل المزامنة النشاط والوزن ونسبة الدهون والكتلة الخالية من الدهون وBMI من «صحتي» إلى هذا الملف. لا تُرسل صورًا أو تقارير كاملة.</p><details open><summary>لديك ربط يعمل؟ أضف قياسات الجسم دون تغيير المفتاح</summary><p>في Health Auto Export ← Automations ← Fitness Tracker ← Select Health Metrics، أضف Weight &amp; Body Mass وBody Fat Percentage وLean Body Mass وBody Mass Index مع إبقاء مؤشرات النشاط. اسمح بقراءتها من صحتي ثم نفّذ التصدير. احتفظ بإعداد Days وAggregate Data. لا تحتاج إنشاء مفتاح بديل.</p><p>فعّل كتابة القياسات إلى صحتي من تطبيق الميزان أو InBody. تأكد أن القياسات تخص صاحب ملف الاستقبال؛ لا تستخدم نفس تصدير صحتي لأفراد مختلفين.</p></details><ol class="health-steps"><li>في Mi Fitness: الملف الشخصي ← بيانات الجهات الخارجية ← صحتي. فعّل البيانات المتاحة وتأكد من ظهورها في صحتي.</li><li>ثبّت <a href="https://www.healthyapps.dev/" target="_blank" rel="noopener noreferrer">Health Auto Export</a> واسمح له بقراءة مؤشرات النشاط وقياسات الجسم المطلوبة. التصدير التلقائي قد يتطلب اشتراكًا داخل التطبيق؛ راجع السعر قبل الشراء.</li><li>أنشئ مفتاحًا لهذا الملف، ثم اضغط «إعداد الربط في التطبيق الوسيط». إذا لم يفتح من داخل ChatGPT، افتح هذه الصفحة في Safari.</li><li>داخل التطبيق الوسيط راجع الإعدادات، ثم نفّذ Manual Export لليوم. ارجع هنا واضغط «تحديث الحالة» حتى يظهر وقت الاستقبال.</li></ol><p class="sub">التحديث المطلوب كل ساعة مع إعادة إرسال آخر ٧ أيام لتحديث الإجماليات. قد يتأخر بسبب قفل الهاتف أو قيود الخلفية. هذه مزامنة قراءة من صحتي؛ لا تكتب في صحتي ولا تسجل أوزان وعدات تمارين المقاومة.</p><div class="quick-buttons"><button class="button" data-health-create>${h?.linked?'إنشاء مفتاح بديل':'إنشاء مفتاح الربط'}</button>${h?.linked?'<button class="button secondary" data-health-revoke>إيقاف الربط</button>':''}</div>${token?`<div class="health-key-box"><p>هذا المفتاح يسمح بإرسال النشاط وقياسات الجسم إلى هذا الملف فقط، ولا يسمح بقراءة سجلاتك. يظهر هنا لهذه الجلسة فقط؛ لا تشاركه.</p><a class="button" href="${esc(healthAutomationURL(token))}" referrerpolicy="no-referrer">إعداد الربط في التطبيق الوسيط</a><details><summary>الإعداد اليدوي ونسخ المفتاح</summary><label class="field">URL<input readonly value="${esc(location.origin+'/api/health-import')}"></label><p>Automation Type: REST API · Method: POST · Data Type: Health Metrics · Format: JSON</p><p>Aggregate Data: ON · Interval: Days · Period: Previous 7 Days · Batch Requests: OFF</p><p>المؤشرات: Step Count، Walking + Running Distance، Active Energy، Apple Exercise Time، Weight &amp; Body Mass، Body Fat Percentage، Lean Body Mass، Body Mass Index.</p><label class="field">Header: X-Health-Key<input id="healthKeyValue" type="password" readonly value="${token}" autocomplete="off"></label><button class="button secondary" data-health-copy>نسخ المفتاح</button><p class="sub">يصلح المفتاح لمدة سنة، أو حتى تغييره أو إيقاف الربط. لا تضع المفتاح في رابط الاستقبال.</p></details></div>`:''}<details><summary>كيف تُحتسب البيانات؟</summary><p>كل مؤشر له إجمالي واحد لكل تاريخ. إعادة الإرسال تحدّثه ولا تضيفه مرة أخرى. خطوات صحتي تحل محل الرقم اليدوي في العرض عندما تتوفر؛ يبقى السجل اليدوي محفوظًا. السعرات النشطة لا تزيد هدف الأكل تلقائيًا. إيقاف الربط يمنع الإرسال الجديد ويحتفظ بالتاريخ السابق.</p><p>إذا ظهر daily_aggregation_required في التطبيق الوسيط، فعّل التجميع حسب Days. إذا ظهر invalid_health_key، أنشئ مفتاحًا بديلًا وأعد الإعداد.</p><a href="https://help.healthyapps.dev/en/health-auto-export/automations/deep-link/" target="_blank" rel="noopener noreferrer">دليل التطبيق الوسيط</a></details></section>`}
function renderHealthDaily(){const h=healthForDate(selected);return `<section class="card"><div class="card-head"><div><h2>نشاطي من صحتي</h2><p class="sub">${pretty(selected)} · ${esc(profileName())}</p></div><a class="button secondary" href="#settings">إعداد الربط</a></div><p class="sub" data-health-status>${esc(healthStatus())}</p>${h&&['steps','distance','activeCalories','exerciseMinutes'].some(k=>h[k]!=null)?`<div class="mini-grid">${[['steps','الخطوات','خطوة'],['distance','المشي والجري','كم'],['activeCalories','السعرات النشطة','سعرة'],['exerciseMinutes','وقت التمرين','دقيقة']].map(([k,label,u])=>`<div class="mini"><small>${label}</small><strong>${h[k]==null?'—':fmt(h[k])} <small>${u}</small></strong></div>`).join('')}</div><p class="sub">المصدر: Apple Health عبر Health Auto Export. الإجماليات تتحدث عند الاستقبال؛ الشرطة تعني أن المؤشر لم يصل.</p>`:'<p>لم تصل بيانات لهذا التاريخ. بعد الإعداد، صدّر اليوم من التطبيق الوسيط والهاتف مفتوح.</p>'}</section>`}
const settingsBeforeHealth=renderSettings;renderSettings=()=>renderHealthSettings()+settingsBeforeHealth();const activityBeforeHealth=renderActivity;renderActivity=()=>renderHealthDaily()+activityBeforeHealth();
document.addEventListener('click',async e=>{const create=e.target.closest('[data-health-create]'),revoke=e.target.closest('[data-health-revoke]'),copy=e.target.closest('[data-health-copy]');if(e.target.closest('[data-health-refresh]'))return refreshHealth();if(copy){try{await navigator.clipboard.writeText(healthKey);notify('تم نسخ المفتاح')}catch{$('#healthKeyValue').type='text';$('#healthKeyValue').select();notify('اضغط مطولًا لنسخ المفتاح')}return}if(!create&&!revoke)return;if(create&&healthSnapshot?.linked&&!confirm('إنشاء مفتاح جديد يوقف المفتاح السابق. هل تريد إعادة إعداد الربط؟'))return;if(revoke&&!confirm('إيقاف استقبال النشاط؟ ستبقى البيانات السابقة محفوظة.'))return;const btn=create||revoke,profile=activeProfile,account=accountScope;btn.disabled=true;try{const b=await healthRequest(create?'POST':'DELETE');if(profile!==activeProfile||account!==accountScope)return;healthKey=create?b.token:'';healthKeyProfile=profile;await refreshHealth();render()}catch(err){notify(err.message,true)}finally{btn.disabled=false}});
window.addEventListener('hashchange',()=>refreshHealth());window.addEventListener('focus',()=>refreshHealth());document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshHealth()});document.addEventListener('change',e=>{if(e.target.id==='selectedDate')refreshHealth()});setInterval(refreshHealth,15000);refreshHealth();

// Daily body aggregates remain separate from hand-entered and device reports.
function healthBodyRows(){
 if(healthSnapshot?.profile!==activeProfile||healthSnapshot?.account!==accountScope)return [];
 const days=new Map();
 for(const r of healthSnapshot.readings||[]){if(!['weight','bfr','leanWeight','bmi'].includes(r.metric))continue;const row=days.get(r.day)||{id:'health-body:'+r.day,date:r.day,device:'Apple Health — تجميع يومي',source:'apple-health-daily',healthAggregate:true};row[r.metric]=r.value;row.updatedAt=!row.updatedAt||r.updatedAt>row.updatedAt?r.updatedAt:row.updatedAt;days.set(r.day,row)}
 return [...days.values()].sort((a,b)=>b.date.localeCompare(a.date));
}
function renderHealthBody(){
 const rows=healthBodyRows(),last=rows[0];
 return `<section class="card" id="healthBody"><div class="card-head"><div><h2>قياسات الجسم من صحتي</h2><p class="sub">${esc(profileName())} · ${last?pretty(last.date):'بانتظار القياسات'}</p></div><button class="button secondary" data-health-refresh>تحديث الحالة</button></div><p class="sub">${last?'آخر استقبال للقياسات: '+esc(new Date(last.updatedAt).toLocaleString('ar-SA')):'لم تصل قياسات جسم بعد؛ نجاح استقبال النشاط وحده لا يعني وصول الوزن والدهون.'}</p>${last?`<div class="mini-grid">${[['weight','الوزن','كجم'],['bfr','الدهون','%'],['leanWeight','الكتلة الخالية من الدهون','كجم'],['bmi','BMI','']].map(([k,l,u])=>`<div class="mini"><small>${l}</small><strong>${last[k]==null?'—':fmt(last[k])} <small>${u}</small></strong></div>`).join('')}</div><details><summary>سجل القياسات المستقبلة (${rows.length} يومًا)</summary><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>الوزن كجم</th><th>الدهون %</th><th>دون دهون كجم</th><th>BMI</th><th>التقرير</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${esc(m.date)}</td>${['weight','bfr','leanWeight','bmi'].map(k=>`<td>${m[k]==null?'—':fmt(m[k])}</td>`).join('')}<td>${m.weight?`<button class="text-button" data-health-body-report="${esc(m.id)}">عرض التحليل</button>`:'يلزم وزن لنفس التاريخ'}</td></tr>`).join('')}</tbody></table></div></details>`:'<p>أضف مؤشرات الجسم إلى ربط Health Auto Export الحالي، وتأكد أن تطبيق الميزان يكتب القياسات إلى صحتي.</p>'}<p class="notice">القيم مجمّعة حسب اليوم وقد تمثل متوسط عدة قراءات؛ ليست تقرير InBody كاملًا ولا نخلطها بقياسات يوم آخر. الكتلة الخالية من الدهون ليست العضلات الهيكلية SMM. المصدر المعلن هو صحتي؛ لا يمكن تأكيد جهاز القياس الأصلي من هذا التصدير.</p><a href="#settings" class="button secondary">إعداد ربط قياسات الجسم</a></section>`;
}
const recordsBeforeHealth=bodyRecords;
bodyRecords=()=>[...recordsBeforeHealth(),...healthBodyRows().filter(m=>m.weight&&m.date<=today())].sort((a,b)=>(b.measuredAt||b.date).localeCompare(a.measuredAt||a.date));
const bodyBeforeHealth=renderBodyCoach;renderBodyCoach=()=>renderHealthBody()+bodyBeforeHealth();
const progressBeforeHealth=renderProgress;renderProgress=()=>renderHealthBody()+progressBeforeHealth();
document.addEventListener('click',e=>{const b=e.target.closest('[data-health-body-report]');if(!b)return;bodyReportId=b.dataset.healthBodyReport;location.hash='body';render()});
